const sd = $getWorkflowStaticData('global');
for (const k of ['seenTasks','seenDeals','seenMail','seenCal']) sd[k] = sd[k] || {};
const first = !sd.initialized;
const get = n => { try { return $(n).all().map(i => i.json).filter(j => j && Object.keys(j).length); } catch (e) { return []; } };
const tasks = get('Read Open Tasks'), deals = get('Read Deals'), mails = get('Read New Mail'), cal = get('Read Calendar');
const now = Date.now(); const lines = [];
const fmt = d => new Date(d).toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });
for (const t of tasks) {
  const needs = t.human_action_required === true || String(t.blocked_by || '').toLowerCase() === 'baher' || t.assigned_to_agent === 'baher_owner';
  if (!needs || !t.task_id || sd.seenTasks[t.task_id]) continue;
  sd.seenTasks[t.task_id] = now;
  if (!first) lines.push('🟠 مهمة عليك أنت: ' + String(t.objective || t.task_id).slice(0, 120) + '\n   المطلوب: ' + String(t.next_action || '').slice(0, 160) + (t.due_at ? '\n   الموعد: ' + fmt(t.due_at) : ''));
}
for (const d of deals) {
  if (!d.deal_id || sd.seenDeals[d.deal_id]) continue;
  sd.seenDeals[d.deal_id] = now;
  if (!first) lines.push('🟢 صفقة/عميل جديد: ' + (d.client_name || '—') + ' · ' + (d.service || '') + ' · المرحلة ' + (d.stage || '') + ' · المالك ' + (d.deal_owner || ''));
}
for (const m of mails) {
  const id = m.id || m.threadId; if (!id || sd.seenMail[id]) continue;
  sd.seenMail[id] = now;
  const from = m.from || m.From || (m.headers && m.headers.from) || ''; const subj = m.subject || m.Subject || (m.headers && m.headers.subject) || '(بلا عنوان)';
  if (!first) lines.push('📧 بريد جديد: ' + String(subj).slice(0, 90) + '\n   من: ' + String(from).slice(0, 80));
}
for (const e of cal) {
  const st = (e.start && (e.start.dateTime || e.start.date)) || null; if (!st || !e.id) continue;
  const mins = (new Date(st).getTime() - now) / 60000; const title = e.summary || 'موعد'; const loc = e.location ? ' · ' + e.location : '';
  if (mins > 30 && mins <= 60 && !sd.seenCal[e.id + '-1h']) { sd.seenCal[e.id + '-1h'] = now; lines.push('⏰ بعد ساعة: ' + title + ' — ' + fmt(st) + loc); }
  if (mins > 23 * 60 && mins <= 24 * 60 && !sd.seenCal[e.id + '-1d']) { sd.seenCal[e.id + '-1d'] = now; lines.push('📅 بكرة: ' + title + ' — ' + fmt(st) + loc); }
}
for (const k of ['seenTasks','seenDeals','seenMail','seenCal']) { const o = sd[k]; const ks = Object.keys(o); if (ks.length > 800) ks.sort((a, b) => o[a] - o[b]).slice(0, ks.length - 600).forEach(x => delete o[x]); }
if (first) { sd.initialized = now; return [{ json: { text: 'فرح هنا 👋 صار عندي متابعة استباقية: أنبّهك هنا فور أي مهمة عليك، أو عميل/صفقة جديدة، أو بريد جديد، وأذكّرك بمواعيدك قبل يوم وقبل ساعة، ومعك ملخص كل صباح ٨:٠٠. سجّلت الوضع الحالي كنقطة بداية (' + tasks.length + ' مهمة مفتوحة، ' + deals.length + ' صفقة).' } }]; }
if (!lines.length) return [];
const stamp = new Date().toLocaleTimeString('ar-SA', { timeZone: 'Asia/Riyadh', hour: '2-digit', minute: '2-digit' });
return [{ json: { text: 'فرح — تحديث ' + stamp + '\n\n' + lines.slice(0, 8).join('\n\n') + (lines.length > 8 ? '\n\n…و' + (lines.length - 8) + ' أخرى، اسألني عنها.' : '') + '\n\nردّ عليّ هنا وأكمل معك.' } }];

const g = n => { try { return $(n).all().map(i => i.json).filter(j => j && Object.keys(j).length); } catch (e) { return []; } };
const deals = g('Read All Deals'), tasks = g('Read All Tasks'), kpis = g('Read KPIs');
const by = (arr, k) => arr.reduce((m, x) => { const v = String(x[k] || '—'); m[v] = (m[v] || 0) + 1; return m; }, {});
const sum = (arr, k) => arr.reduce((s, x) => s + (Number(x[k]) || 0), 0);
const days = d => Math.round((Date.now() - new Date(d).getTime()) / 864e5);
const openT = tasks.filter(t => t.status === 'queued' || t.status === 'in_progress');
const facts = {
  date: new Date().toLocaleDateString('ar-SA', { timeZone: 'Asia/Riyadh', weekday: 'long', day: 'numeric', month: 'long' }),
  deals: { count: deals.length, by_stage: by(deals, 'stage'), by_payment: by(deals, 'payment_status'), deal_value_total: sum(deals, 'deal_value'), paid_total: sum(deals, 'paid_amount'), invoiced_total: sum(deals, 'invoiced_amount'),
    blocked: deals.filter(d => d.blocked_by || d.human_action_required).map(d => ({ client: d.client_name, stage: d.stage, blocked_by: d.blocked_by, next: d.next_action })).slice(0, 10),
    stale_over_5_days: deals.filter(d => d.updated_at && days(d.updated_at) > 5 && !/delivered|lost|closed/i.test(d.stage || '')).map(d => ({ client: d.client_name, stage: d.stage, days: days(d.updated_at) })).slice(0, 10) },
  tasks: { count: tasks.length, by_status: by(tasks, 'status'), open_by_agent: by(openT, 'assigned_to_agent'),
    needs_owner: openT.filter(t => t.human_action_required === true || t.assigned_to_agent === 'baher_owner').map(t => ({ id: t.task_id, objective: t.objective, next: t.next_action, due: t.due_at })).slice(0, 10),
    overdue: openT.filter(t => t.due_at && new Date(t.due_at).getTime() < Date.now()).map(t => ({ id: t.task_id, objective: t.objective, agent: t.assigned_to_agent, due: t.due_at })).slice(0, 10),
    completed_last_24h: tasks.filter(t => t.status === 'completed' && t.updated_at && days(t.updated_at) <= 1).map(t => ({ objective: t.objective, agent: t.assigned_to_agent })).slice(0, 10) },
  kpis: kpis.slice(0, 25)
};
const prompt = 'أنت فرح، رئيسة المكتب التنفيذي لباهر في Business Partner. اكتبي له ملخص الصباح على واتساب بالعربية السعودية، ودّي ومباشر، بلا مجاملات طويلة.\nقاعدة الدليل: لا تذكري رقماً أو اسماً غير موجود في البيانات أدناه. إن كان قسم فارغاً قولي «لا شيء» ولا تخمّني.\nالبنية (كل قسم سطران إلى أربعة، بلا عناوين ماركداون، الإيموجي هو العنوان):\n☀️ صباح الخير + جملة واحدة عن حال الشركة\n✅ الحلو: ما تحرّك وما يبشّر\n⚠️ السيئ: المتعثّر والمتأخر والمعطّل، بالاسم\n🫵 عليك اليوم: ما ينتظر باهر شخصياً فقط، مرتّباً حسب الأثر على الكاش\n📊 أرقام: من ثلاثة إلى خمسة أرقام فقط من البيانات\n\nالبيانات (JSON):\n' + JSON.stringify(facts).slice(0, 9000);
return [{ json: { prompt, facts } }];
